  const RAD = Math.PI / 180, PHI_1 = 12.47 * RAD, PHI_2 = 35.17 * RAD, LON_0 = 80 * RAD;
  const t = phi => Math.tan(Math.PI / 4 + phi / 2);
  const N = Math.log(Math.cos(PHI_1) / Math.cos(PHI_2)) / Math.log(t(PHI_2) / t(PHI_1));
  const F = (Math.cos(PHI_1) * Math.pow(t(PHI_1), N)) / N;
  function lcc(lon, lat) {
    const rho = F / Math.pow(t(lat * RAD), N), theta = N * (lon * RAD - LON_0);
    return { x: rho * Math.sin(theta), y: -rho * Math.cos(theta) };
  }

  const WIDTH = 560;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const ring of [MAINLAND, ...ISLANDS]) for (const [lon, lat] of ring) {
    const p = lcc(lon, lat);
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
  }
  const s = WIDTH / (maxX - minX);

  function project(lon, lat) {
    const p = lcc(lon, lat);
    return { x: (p.x - minX) * s, y: (maxY - p.y) * s };
  }
  const toPath = ring => ring.map(([lon, lat], i) => {
    const { x, y } = project(lon, lat);
    return (i ? "L" : "M") + x.toFixed(1) + " " + y.toFixed(1);
  }).join("") + "Z";

